  if (taskId === 'camera_ready') role = 'camera_ready_zip';
  else if (taskId === PHD_WORKSHOP_POSTER_TASK_ID) role = PHD_WORKSHOP_POSTER_ROLE;
  else if (taskId === BOOK_FORUM_POSTER_TASK_ID) role = BOOK_FORUM_POSTER_FOLDER_ROLE;
