/** Read-only checks for this edition. Run from the Apps Script editor. */
function RUN_CHECK_INSTALLATION() {
  const active=Session.getActiveUser().getEmail(),effective=Session.getEffectiveUser().getEmail();
  if(!active||active!==effective)throw new Error('Run this check from the Apps Script editor as the project owner.');
  const edition=conferenceEdition_(),schemas=[{"key":"acceptedId","tabs":[{"name":"Full Papers","headers":["ID","Title","Authors","All Reviewer Comments"]},{"name":"Projects","headers":["ID","Title","Authors","All Reviewer Comments"]},{"name":"Field Notes","headers":["ID","Title","Authors","All Reviewer Comments"]},{"name":"PhD Workshop","headers":["ID","Title","Authors","All Reviewer Comments"]},{"name":"Book Forum","headers":["ID","Title","Authors","All Reviewer Comments"]}]},{"key":"authorMasterId","tabs":[{"name":"Settings","headers":["Key","Value","Notes"]},{"name":"Submissions","headers":["Paper ID","Original Title","Normalized Original Title","Final Title","Track","Volume","Corresponding Author","Corresponding Email","Presenting Author","Presenting Email","Submission Folder ID","Portal Enabled","Overall Status","Proof Version","Proof Due Label","Last Updated"]},{"name":"Task_Status","headers":["Paper ID","Task ID","Task Name","Status","Submitted At","Approved At","Action Required Note","Last Updated"]},{"name":"Task_Data","headers":["Paper ID","Task ID","Data JSON","Last Updated"]},{"name":"Reviewer_Feedback","headers":["Paper ID","Review Label","Reviewer Comment","Source","Imported At"]},{"name":"Authors","headers":["Paper ID","Position","Full Name","Email","Affiliation","ORCID","Corresponding","Presenting","Last Updated"]},{"name":"Website_Materials","headers":["Paper ID","Final Title","Category","Abstract","Keywords","Corresponding Email","Last Updated"]},{"name":"Website_Images","headers":["Paper ID","Image Slot","Drive File ID","File Name","Caption","Credit","Alt Text","Active","Last Updated"]},{"name":"File_Registry","headers":["Paper ID","Task ID","Role","Version","Drive File ID","File Name","Original File Name","MIME Type","Size Bytes","Parent Folder ID","Active","Uploaded At"]},{"name":"Folder_Registry","headers":["Paper ID","Folder Role","Folder ID","Folder Name","Last Updated"]},{"name":"Attendance","headers":["Paper ID","Attendance Confirmed","Pre