uest ID","Generated At","Registration ID","Instructor Name","Identity Name","Workshop ID","Workshop Title","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]},{"name":"Presentation_Confirmations","headers":["Paper ID","Status","Confirmed Presenter","Confirmed By","Confirmed At","Notes"]},{"name":"Presentation_Certificate_Log","headers":["Request ID","Generated At","Identity Key","Author Name","Author Email","Track","Paper IDs","Session IDs","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]},{"name":"Session_Chair_Certificate_Log","headers":["Request ID","Generated At","Identity Key","Chair Name","Chair Email","Session IDs","Session Count","Presentation Count","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]},{"name":"Volunteers","headers":["Volunteer ID","Full Name","Affiliation","Name Aliases","Enabled"]},{"name":"Volunteer_Certificate_Log","headers":["Request ID","Generated At","Volunteer ID","Full Name","Affiliation","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]},{"name":"Awards","headers":["Award ID","Award Name","Paper ID","Track","Award Work Title","Award Authors","Enabled"]},{"name":"Award_Certificate_Log","headers":["Request ID","Generated At","Identity Key","Recipient Name","Recipient Email","Award ID","Paper ID","Award Name","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]}]},{"key":"chairCoordinationId","tabs":[{"name":"Sessions","headers":["Session ID","Session title","Date","Start (ET)","End (ET)","Session chair","Chair email"]}]},{"key":"phdMonitorId","tabs":[{"name":"Submission Monitor","headers":["Paper ID","Title","Authors","Corresponding Author","Corresponding Email","Overall Status","Task 1 Metadata + Website","Task 2 Exhibition Poster","Poster File","Task 3 Copyright + Recording Consent","Consent File","Task 4 Attendance","Presenter","Task 5 Indexing","Task 6 Volunteer Preferences","Volunteer Preferences","Other Preference","Available Time Slots","Task 7 Conference Registration","Registration Confirmation File","Last Activity","Last Activity Detail","Last Updated","Submission Folder"]},{"name":"Activity Log","headers":["Timestamp","Paper ID","Title","Event","Task","Detail"]},{"name":"Volunteer Assignments","headers":["Paper ID","Title","Participant / Authors","Volunteer Preferences","Other Preference","Available Time Slots","Preference Submitted","Assigned Role","Shift / Date / Time","Coordinator Notes","Assignment Status"]}]}];
  const moduleName=typeof DEFAULTS!=='undefined'?'author-portal':typeof PROGRAM_CONFIG!=='undefined'?'conference-program':typeof REVIEWER_PORTAL!=='undefined'?'recognition-portal':typeof MAIL_SENDER_!=='undefined'?'presentation-reminders':'calendar-sync';
  const requirements={
    'author-portal':['authorMasterId','acceptedId','presentationId'],
    'conference-program':['authorMasterId','scheduleId'],
    'recognition-portal':['recognitionId'],
    'presentation-reminders':['authorMasterId','presentationId','scheduleId'],
    'calendar-sync':['scheduleId']
  };
  const render=value=>String(value).replace(/\{\{([A-Za-z0-9_]+)\}\}/g,(_,key)=>String(edition[key]??''));
  const checks=[];
  requirements[moduleName].forEach(key=>{
    const id=edition.resources[key];
    if(!id){checks.push({workbook:key,ok:false,problem:'Resource ID is missing.'});return;}
    try {
      const book=SpreadsheetApp.openById(id),spec=schemas.find(b=>b.key===key);
      spec.tabs.forEach(tab=>{
        const name=render(tab.name),sheet=book.getSheetByName(name);
        if(!sheet){checks.push({workbook:key,tab:name,ok:false,problem:'Required tab is missing.'});return;}
        const expected=tab.headers.map(render),actual=sheet.getRange(1,1,1,expected.length).getDisplayValues()[0];
        const ok=expected.every((h,i)=>h===String(actual[i]||''));
        checks.push({workbook:key,tab:name,ok:ok,dataRows:Math.max(0,sheet.getLastRow()-1),problem:ok?'':'Header names or column order differ from the generated template.'});
      });
    }catch(error){checks.push({workbook:key,ok:false,problem:'Cannot read this workbook. Check its ID and the executing account’s access.'});}
  });
  const result={module:moduleName,year:edition.year,ok:checks.every(c=>c.ok),checks:checks};
  console.log(JSON.stringify(result,null,2));return result;
}

