uest ID","Generated At","Registration ID","Instructor Name","Identity Name","Workshop ID","Workshop Title","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]},{"name":"Presentation_Confirmations","headers":["Paper ID","Status","Confirmed Presenter","Confirmed By","Confirmed At","Notes"]},{"name":"Presentation_Certificate_Log","headers":["Request ID","Generated At","Identity Key","Author Name","Author Email","Track","Paper IDs","Session IDs","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]},{"name":"Session_Chair_Certificate_Log","headers":["Request ID","Generated At","Identity Key","Chair Name","Chair Email","Session IDs","Session Count","Presentation Count","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]},{"name":"Volunteers","headers":["Volunteer ID","Full Name","Affiliation","Name Aliases","Enabled"]},{"name":"Volunteer_Certificate_Log","headers":["Request ID","Generated At","Volunteer ID","Full Name","Affiliation","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]},{"name":"Awards","headers":["Award ID","Award Name","Paper ID","Track","Award Work Title","Award Authors","Enabled"]},{"name":"Award_Certificate_Log","headers":["Request ID","Generated At","Identity Key","Recipient Name","Recipient Email","Award ID","Paper ID","Award Name","PDF File ID","PDF File Name","Template File ID","Data Fingerprint"]}]},{"key":"chairCoordinationId","tabs":[{"name":"Sessions","headers":["Session ID","Session title","Date","Start (ET)","End (ET)","Session chair","Chair email"]}]},{"key":"phdMonitorId","tabs":[{"name":"Submission Monitor","headers":["Paper ID","Title","Authors","Corresponding Author","Corresponding Email","Overall Status","Task 1 Metadata + Website","Task 2 Exhibition Poster","Poster File","Task 3 Copyright + Recording Consent","Consent File","Task 4 Attendance","Presenter","Task 5 Indexing","Task 6 Volunteer Preferences","Volunteer Preferences","Other Preference","Available Time Slots","